import{_ as e}from"./chunks/mob2-report-form.a813b616.js";import{_ as t,o as n,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const i="/assets/zones-layers.34e05578.svg",s="/assets/line-to-file.35e58b3e.svg",r="/assets/shift-mode.475731ab.svg",l="/assets/mill-directions.db1053a1.svg",h="/assets/twin-nailing.f9498e73.svg",d="/assets/zip-tree.763e9bc5.svg",S=JSON.parse('{"title":"MOB v2 Machine File","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/panel_mob2/index.md","filePath":"guide/machine_files/formats/panel_mob2/index.md","lastUpdated":1790618281000}'),c={name:"guide/machine_files/formats/panel_mob2/index.md"},p=a('<h1 id="mob-v2-machine-file" tabindex="-1">MOB v2 Machine File <a class="header-anchor" href="#mob-v2-machine-file" aria-label="Permalink to &quot;MOB v2 Machine File&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta — under review</p><p>This page is new and is still being checked against the machines. It may be incomplete or contain mistakes, so do not rely on it alone for production settings. If something here does not match what you see, tell us.</p></div><p>A MOB v2 file tells an H&amp;M panel line what to do with one wall or floor panel: where the frame pieces go, where to nail, screw, mill, saw, drill and glue, and on which face. produuz.it writes it from the IFC model of the panel and from how your production line is set up.</p><p>It is read by the <strong>Mobi One V2</strong>, the <strong>Frame Station V2</strong>, the <strong>Robobrick</strong> and the <strong>Isolation machine</strong>. One file covers every station of the line: the frame, the inside face and the outside face of the panel are all in the same file.</p><nav class="table-of-contents"><ul><li><a href="#how-a-file-is-made">How a file is made</a><ul><li><a href="#zones-and-faces">Zones and faces</a></li><li><a href="#from-a-production-line-to-one-file">From a production line to one file</a></li><li><a href="#what-the-machine-configuration-file-decides">What the machine configuration file decides</a></li></ul></li><li><a href="#creating-the-file">Creating the file</a></li><li><a href="#what-is-in-the-file">What is in the file</a><ul><li><a href="#header">Header</a></li><li><a href="#layers">Layers</a></li><li><a href="#commands">Commands</a></li><li><a href="#an-example">An example</a></li><li><a href="#where-the-operations-come-from">Where the operations come from</a></li></ul></li><li><a href="#job-options">Job options</a><ul><li><a href="#general">General</a></li><li><a href="#framing">Framing</a></li><li><a href="#cladding-options">Cladding options</a></li><li><a href="#mill-and-saw-directions">Mill and saw directions</a></li><li><a href="#tool-ids">Tool IDs</a></li><li><a href="#default-job-options">Default job options</a></li><li><a href="#frame-station-v2">Frame Station V2</a></li><li><a href="#robobrick">Robobrick</a></li><li><a href="#isolation-machine">Isolation machine</a></li></ul></li><li><a href="#output">Output</a></li><li><a href="#when-something-is-wrong">When something is wrong</a></li></ul></nav><h2 id="how-a-file-is-made" tabindex="-1">How a file is made <a class="header-anchor" href="#how-a-file-is-made" aria-label="Permalink to &quot;How a file is made&quot;">​</a></h2><p>Three things decide what ends up in the file: the <strong>zones</strong> of the parts in the model, the <strong>stations</strong> of the production line, and the <strong>machine setup</strong> of each station.</p><h3 id="zones-and-faces" tabindex="-1">Zones and faces <a class="header-anchor" href="#zones-and-faces" aria-label="Permalink to &quot;Zones and faces&quot;">​</a></h3><p>Every part of the panel has a zone, read by your <a href="/guide/management/ifcps/#zone-layer">IFC Parsing Setup</a>.</p><p><img src="'+i+'" alt="A panel cut through its thickness, with its zones"></p><ol><li><strong>Zone 0</strong> is the frame: rails, studs and the other frame woods.</li><li><strong>Negative zones</strong> are the layers of the inside face, counted outwards from the frame: -1 on the frame, -2 on top of -1.</li><li><strong>Positive zones</strong> are the layers of the outside face, counted the same way.</li><li>The <strong>Production starting side</strong> says which face is clad first. See <a href="#general">General</a>.</li></ol><p>A part with no zone is not produced by any station, so it never reaches the file.</p><h3 id="from-a-production-line-to-one-file" tabindex="-1">From a production line to one file <a class="header-anchor" href="#from-a-production-line-to-one-file" aria-label="Permalink to &quot;From a production line to one file&quot;">​</a></h3><p><img src="'+s+'" alt="How the stations of a line become the layers of one file"></p><ol><li>Each <strong>machine station</strong> produces the zones listed in its <strong>Zones</strong> field, with its own machine setup and its own job options. Stations are taken in the order of the line.</li><li><strong>Manual stations</strong> are skipped: they have no machine and write nothing.</li><li>The frame layers come first in the file, for the frame and for the turned panel.</li><li>Then the layers of each station follow, in station order. Within one station the inside zones come first, then the outside ones. A zone with battens gets its batten layer just before its plate layer.</li></ol><p>Rules that follow from this:</p><ul><li><strong>A zone belongs to the first station that lists it.</strong> If two stations list the same zone, only the first produces it. The line form warns about it: <em>Please note that you have the zone 0 in stations: …</em></li><li><strong>A zone that no station lists is not produced</strong>, and nothing warns you. Check the Zones of your stations against the zones your parsing setup gives.</li><li><strong>The station that owns zone 0 decides for the whole line</strong>: its <strong>Production starting side</strong> and <strong>Shift mode</strong>, and which operation drawings are made (the <strong>SVG Drawings</strong> switches of its machine setup). Give zone 0 to exactly one station.</li><li><strong>Every machine station must have one of the MOB v2 machines listed above.</strong> Put saws and plate cutters on their own lines, and put the <em>H&amp;M Mobi One V2 Production Line</em> setup on the line itself, never on a station. See <a href="/guide/management/production_lines/#the-machine-of-a-line">The machine of a line</a>.</li><li><strong>Two stations must not share one machine setup.</strong> Create one setup per station, even when the machines are identical.</li></ul><h3 id="what-the-machine-configuration-file-decides" tabindex="-1">What the machine configuration file decides <a class="header-anchor" href="#what-the-machine-configuration-file-decides" aria-label="Permalink to &quot;What the machine configuration file decides&quot;">​</a></h3><p>Each Mobi One, Frame Station, Robobrick and Isolation setup takes the machine&#39;s own configuration file (XML), uploaded in the <strong>Machine file</strong> tab of the setup. It tells produuz.it what the machine has:</p><ul><li><strong>Which tools exist.</strong> The tool fields of the report form only offer the tools the file declares. See <a href="#tool-ids">Tool IDs</a>.</li><li><strong>Which operations are possible.</strong> Plate nailing, screwing, milling, sawing and gluing are only written when the machine has the unit for them. Frame nailing needs a framing unit.</li><li><strong>Flooring.</strong> A file with flooring stations turns the frame layer into flooring clamp commands instead of frame nailing.</li><li><strong>Sizes</strong> used by <a href="#general">trimming</a>: the maximum width, and the maximum length when the setup does not set its own.</li><li><strong>Machine zero</strong>, when the setup&#39;s <strong>Machine zero</strong> is <em>File info</em>. See <a href="/guide/machine_files/machines/mobi_one/#machine-setup">Mobi One</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Upload the configuration file first</p><p>Without it the report form offers almost no tools, and the file cannot be generated: the panel fails with an error.</p></div><h2 id="creating-the-file" tabindex="-1">Creating the file <a class="header-anchor" href="#creating-the-file" aria-label="Permalink to &quot;Creating the file&quot;">​</a></h2><ol><li>Open <strong>Production files</strong> in a project and press <strong>New production file</strong>.</li><li>Pick <strong>MOB v2 Machine File</strong> as the <strong>Report Type</strong>.</li><li>Pick the <strong>Production line</strong>. One <strong>Station Job Options</strong> block appears for each station with a MOB v2 machine, filled in with the default job options of its machine setup.</li><li>Change the options you need for this file. They are explained <a href="#job-options">below</a>.</li><li>Select the panels and press <strong>Submit</strong>.</li></ol><p><img src="'+e+`" alt="The report form for a MOB v2 file"></p><ol><li><strong>MOB v2 Machine File</strong> as the report type.</li><li>The document status.</li><li>One <strong>Station Job Options</strong> block per machine station.</li><li>The production line the file is made for.</li><li>The panels to include.</li><li><strong>Submit</strong>.</li></ol><p>The same file type can also be generated from a <a href="/guide/reports/#generation-templates">generation template</a>, and on its own when a design finishes its analysis, with an <a href="/guide/management/production_lines/#action-triggers">action trigger</a>. The <a href="/guide/management/tools/">Mobfile Generator</a> makes MOB v2 files from files that are not in a project.</p><h2 id="what-is-in-the-file" tabindex="-1">What is in the file <a class="header-anchor" href="#what-is-in-the-file" aria-label="Permalink to &quot;What is in the file&quot;">​</a></h2><p>A MOB v2 file is plain text, one command per row, each row ending in <code>;</code>.</p><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><table><thead><tr><th>Row</th><th>What it holds</th></tr></thead><tbody><tr><td><code>VERSION</code></td><td>Always <code>3.00</code>.</td></tr><tr><td><code>TXT</code></td><td>Comment rows: design name and id, project, the machine zeros, the shifts and the date the file was made.</td></tr><tr><td><code>REIHE</code></td><td>The production starting side, <code>inside</code> or <code>outside</code>.</td></tr><tr><td><code>ELN</code></td><td>The design name.</td></tr><tr><td><code>ELM</code></td><td>Length, height and total thickness of the panel, in mm.</td></tr></tbody></table><h3 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h3><p>The rest of the file is a list of layers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">Layer, &lt;zone&gt;, &lt;name&gt;, &lt;type&gt;, &lt;x shift&gt;, &lt;y shift&gt;, &lt;length&gt;, &lt;height&gt;;</span></span>
<span class="line"><span style="color:#e1e4e8;">... commands ...</span></span>
<span class="line"><span style="color:#e1e4e8;">End Layer, &lt;zone&gt;;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">Layer, &lt;zone&gt;, &lt;name&gt;, &lt;type&gt;, &lt;x shift&gt;, &lt;y shift&gt;, &lt;length&gt;, &lt;height&gt;;</span></span>
<span class="line"><span style="color:#24292e;">... commands ...</span></span>
<span class="line"><span style="color:#24292e;">End Layer, &lt;zone&gt;;</span></span></code></pre></div><p>The name is <code>FRAMING</code> for the frame, and the plate thickness, material and zone for a plate layer (<code>12 mm OSB -1</code>). The shifts are only filled in with <strong>Shift on layers</strong>. See <a href="#general">Shift mode</a>.</p><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><table><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>BR</code>, <code>TR</code>, <code>HC</code>, <code>VC</code>, <code>AC4</code></td><td>The frame map: bottom rail, top rail, horizontal pieces, vertical pieces (studs), and pieces with angled cuts.</td></tr><tr><td><code>NRY</code></td><td>Frame nailing: where the rails are nailed into each stud, and how many nails.</td></tr><tr><td><code>NRYA</code></td><td>Nailing through extra rails into the frame.</td></tr><tr><td><code>FLOORING</code>, <code>FT1</code>…<code>FT6</code></td><td>Flooring clamps, instead of frame nailing, when the machine has flooring stations.</td></tr><tr><td><code>OS</code></td><td>A plate: its size, position and material.</td></tr><tr><td><code>BA</code></td><td>A batten.</td></tr><tr><td><code>NRZ</code></td><td>A plate nail line with one head.</td></tr><tr><td><code>NRZ1</code> + <code>NRZ2</code></td><td>A plate nail line split between two heads that nail at the same time.</td></tr><tr><td><code>BNRZV</code></td><td>A batten nail line.</td></tr><tr><td><code>SCW</code></td><td>Screwing.</td></tr><tr><td><code>PSG</code> + <code>PP</code></td><td>A milling or sawing path: <code>PSG</code> starts it, each <code>PP</code> is a point.</td></tr><tr><td><code>MP</code></td><td>A round hole or a drilling.</td></tr><tr><td><code>ELPS</code></td><td>An elliptical hole.</td></tr><tr><td><code>GLUE</code>, <code>TWINGLUE</code></td><td>Glue lines, with one head or two.</td></tr><tr><td><code>MSN</code>, <code>MSNGLUE</code></td><td>Bricks and their glue (Robobrick).</td></tr><tr><td><code>INS</code></td><td>Insulation shots (Isolation machine).</td></tr></tbody></table><h3 id="an-example" tabindex="-1">An example <a class="header-anchor" href="#an-example" aria-label="Permalink to &quot;An example&quot;">​</a></h3><p>The start of a real file, shortened:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">VERSION       3.00;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # MOB2 Conversion by Produuz.it;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # Design name: TEST1;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # Machine Zeros / Inside: Right Top / Outside: Right Top;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # Shifts / X in: 0  /  Y in: 0  /  X out: 0.0  /  Y out: 0.0 / X RB: 0  /  Y RB: 0;</span></span>
<span class="line"><span style="color:#e1e4e8;">REIHE     inside;</span></span>
<span class="line"><span style="color:#e1e4e8;">ELN      TEST1;</span></span>
<span class="line"><span style="color:#e1e4e8;">ELM   4078,  2630,    69,     1,     0,     0;</span></span>
<span class="line"><span style="color:#e1e4e8;">Layer,     -1,   FRAMING,     1,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#e1e4e8;">BR   1351,    44,    44,     0,     0,        01,H214 VUREN-C 44.0x44.0,     0,     0;</span></span>
<span class="line"><span style="color:#e1e4e8;">TR   1351,    44,    44,     0,  2586,        01,H454 VUREN-C 44.0x44.0,     0,     1;</span></span>
<span class="line"><span style="color:#e1e4e8;">VC   2542,    44,    44,  1307,    44,        01,H216 VUREN-C 44.0x44.0,     0,    11;</span></span>
<span class="line"><span style="color:#e1e4e8;">End Layer,     -1;</span></span>
<span class="line"><span style="color:#e1e4e8;">Layer,     -1,12 mm FERMACELL -1,   110,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#e1e4e8;">OS   1200,  2627,    12,   148,     3,     0,12.5 FERMACELL 1200x2627,    44,     1;</span></span>
<span class="line"><span style="color:#e1e4e8;">PSG;</span></span>
<span class="line"><span style="color:#e1e4e8;">MP    347,  2480,  30.0,    12,  2228,    56;</span></span>
<span class="line"><span style="color:#e1e4e8;">End Layer,     -1;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">VERSION       3.00;</span></span>
<span class="line"><span style="color:#24292e;">TXT # MOB2 Conversion by Produuz.it;</span></span>
<span class="line"><span style="color:#24292e;">TXT # Design name: TEST1;</span></span>
<span class="line"><span style="color:#24292e;">TXT # Machine Zeros / Inside: Right Top / Outside: Right Top;</span></span>
<span class="line"><span style="color:#24292e;">TXT # Shifts / X in: 0  /  Y in: 0  /  X out: 0.0  /  Y out: 0.0 / X RB: 0  /  Y RB: 0;</span></span>
<span class="line"><span style="color:#24292e;">REIHE     inside;</span></span>
<span class="line"><span style="color:#24292e;">ELN      TEST1;</span></span>
<span class="line"><span style="color:#24292e;">ELM   4078,  2630,    69,     1,     0,     0;</span></span>
<span class="line"><span style="color:#24292e;">Layer,     -1,   FRAMING,     1,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#24292e;">BR   1351,    44,    44,     0,     0,        01,H214 VUREN-C 44.0x44.0,     0,     0;</span></span>
<span class="line"><span style="color:#24292e;">TR   1351,    44,    44,     0,  2586,        01,H454 VUREN-C 44.0x44.0,     0,     1;</span></span>
<span class="line"><span style="color:#24292e;">VC   2542,    44,    44,  1307,    44,        01,H216 VUREN-C 44.0x44.0,     0,    11;</span></span>
<span class="line"><span style="color:#24292e;">End Layer,     -1;</span></span>
<span class="line"><span style="color:#24292e;">Layer,     -1,12 mm FERMACELL -1,   110,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#24292e;">OS   1200,  2627,    12,   148,     3,     0,12.5 FERMACELL 1200x2627,    44,     1;</span></span>
<span class="line"><span style="color:#24292e;">PSG;</span></span>
<span class="line"><span style="color:#24292e;">MP    347,  2480,  30.0,    12,  2228,    56;</span></span>
<span class="line"><span style="color:#24292e;">End Layer,     -1;</span></span></code></pre></div><h3 id="where-the-operations-come-from" tabindex="-1">Where the operations come from <a class="header-anchor" href="#where-the-operations-come-from" aria-label="Permalink to &quot;Where the operations come from&quot;">​</a></h3><ul><li><strong>Plate nail lines</strong> come from the nail line elements drawn in the model, recognised by the <strong>Plate Nail Lines</strong> rule of your parsing setup. Their spacing is the model&#39;s <strong>Nail/Screw CTC</strong> when it has one, otherwise the <strong>Default value for CTC in plates nailing</strong> of the machine setup, otherwise 150 mm. The machine spreads the nails evenly over the line.</li><li><strong>Frame nailing</strong> follows the nailing matrix of the machine setup when <strong>Use Custom Matrix pattern</strong> is on, and an automatic rule otherwise. Frame nails drawn in the model always win.</li><li><strong>Holes</strong> in the plates are found on their own, from the openings in the plate outline, even when the model has no milling. Milling, sawing and drilling elements of the model are added to them.</li><li><strong>Lockout areas</strong> in the model cut the nail lines that cross them.</li></ul><p>See: <a href="/guide/management/ifcps/#operations-and-machines">Operations and machines</a></p><h2 id="job-options" tabindex="-1">Job options <a class="header-anchor" href="#job-options" aria-label="Permalink to &quot;Job options&quot;">​</a></h2><p>These are the options of a Mobi One V2 station, with the labels of the report form. Frame Station V2, Robobrick and Isolation have their own, listed at the end.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><table><thead><tr><th>Option</th><th>Choices</th><th>Default</th></tr></thead><tbody><tr><td><strong>Production starting side</strong></td><td>inside, outside</td><td>inside</td></tr><tr><td><strong>Shift mode</strong></td><td>No shift, Shift on layers, Shift on operations</td><td>Shift on operations</td></tr><tr><td><strong>File generation with operations that exceeds the machine sizes</strong></td><td>Trim operations up to max size, Do not generate the layer, Generate it anyway</td><td>Generate it anyway</td></tr></tbody></table><p><strong>Production starting side</strong> says which face is clad first, and so how the panel is measured and in which order the layers come. The value of the station that owns zone 0 applies to the whole line.</p><p><strong>Shift mode</strong> corrects for how the panel lies against the stops of the table.</p><p><img src="`+r+'" alt="The shift: how the panel lies against the stops"></p><ol><li>The panel is pushed against the X and Y stops. When the outermost stud or rail is set back from the edge, because a plate overhangs it for example, the frame is not where the model says. The shift is that distance. The stop height used to decide what touches the stop is the <strong>Blocker Height X / Y</strong> of the machine setup.</li><li>The three modes decide where the shift goes. The shifts are always printed in the header, in the <em>Shifts</em> row.</li></ol><p><strong>File generation with operations that exceeds the machine sizes</strong> decides what happens when an operation reaches past what the machine can do:</p><ul><li><strong>Generate it anyway</strong> writes every operation as it is.</li><li><strong>Trim operations up to max size</strong> leaves out the operations that start beyond the machine size, and shortens the ones that cross it. Studs beyond it get no frame nailing.</li><li><strong>Do not generate the layer</strong> leaves out the frame nailing beyond the machine size. At the moment the plate layers are written as with <em>Generate it anyway</em>.</li></ul><p>The machine size is the <strong>Max Wall Length for X axis</strong> of the machine setup for the length, and the maximum width of the configuration file. When the machine setup leaves its length empty, the length of the configuration file is used.</p><h3 id="framing" tabindex="-1">Framing <a class="header-anchor" href="#framing" aria-label="Permalink to &quot;Framing&quot;">​</a></h3><table><thead><tr><th>Option</th><th>Default</th></tr></thead><tbody><tr><td><strong>Use Custom Matrix pattern</strong></td><td>Off</td></tr></tbody></table><p>On: frame nails follow the <strong>Nailing matrix by beam size</strong> of the machine setup, with its nail columns and its per-class matrices. Off: an automatic rule places them from the paddings and the minimum distance between nails of the machine setup. See <a href="/guide/machine_files/machines/mobi_one/#machine-setup">Mobi One</a>.</p><h3 id="cladding-options" tabindex="-1">Cladding options <a class="header-anchor" href="#cladding-options" aria-label="Permalink to &quot;Cladding options&quot;">​</a></h3><table><thead><tr><th>Option</th><th>Default</th></tr></thead><tbody><tr><td><strong>Plates nailing pattern</strong></td><td>Regular pattern</td></tr><tr><td><strong>Minimum panel height for twin nailing</strong></td><td>0</td></tr></tbody></table><p><strong>Plates nailing pattern</strong> has no effect at the moment. Nail lines with one head are always put in the shortest order, and lines with two heads in the regular order.</p><p><strong>Minimum panel height for twin nailing</strong>: panels lower than this height (mm) are always nailed with one head, the first one, even when a twin nailer is set. 0 turns it off.</p><h3 id="mill-and-saw-directions" tabindex="-1">Mill and saw directions <a class="header-anchor" href="#mill-and-saw-directions" aria-label="Permalink to &quot;Mill and saw directions&quot;">​</a></h3><p><img src="'+l+'" alt="Mill directions on each face, for contours and holes"></p><ol><li><strong>Inside Contour</strong>: the outer edge of the plates on the inside face. Counter clockwise by default.</li><li><strong>Inside Holes</strong>: holes with straight edges on the inside face. Clockwise by default.</li><li>Round and elliptical holes keep their own direction and do not follow the Holes setting.</li><li><strong>Outside Contour</strong>: the outer edge on the outside face. Clockwise by default.</li><li><strong>Outside Holes</strong>. Counter clockwise by default.</li><li>Round holes, as in 3.</li></ol><p>The four <strong>(Saw)</strong> settings do the same for sawing paths. A form saved before they existed takes the milling directions.</p><h3 id="tool-ids" tabindex="-1">Tool IDs <a class="header-anchor" href="#tool-ids" aria-label="Permalink to &quot;Tool IDs&quot;">​</a></h3><p>The tool fields only list the tools that the configuration file of the machine declares. A tool missing from the list is missing from the file: upload the configuration file again after the machine changes.</p><p><strong>Plates Nailer Tool ID</strong> is set per zone and face, for zones 1 to 3.</p><p><img src="'+h+'" alt="One head, or two heads nailing at the same time"></p><ol><li><strong>One number</strong> (<code>24</code>, <code>25</code>, <code>26</code> on the left carriage, <code>44</code>, <code>45</code>, <code>46</code> on the right) nails the whole line with that head.</li><li><strong>Two numbers</strong> (<code>25+45</code>) split each line between two heads that nail at the same time: the first takes the lower part of the line, the second the upper part. This is only offered when the machine has both heads.</li></ol><p>Two more choices take the tool from the model, from the tool id of each nail line:</p><ul><li><strong>Single nailing from model</strong> uses one head per line, the one the model names.</li><li><strong>Twin nailing from model</strong> uses the pair of the tool named by the first line of the zone, for every line of that zone.</li></ul><p>On a machine with twin nailers the right-hand heads (44, 45, 46) are not offered alone.</p><table><thead><tr><th>Field</th><th>Choices</th><th>Default</th></tr></thead><tbody><tr><td><strong>Plates Nailer Tool ID</strong> zone 1–3 Inside / Outside</td><td>the nailers of the machine, their twin pairs, <em>Single nailing from model</em>, <em>Twin nailing from model</em></td><td>5</td></tr><tr><td><strong>Screwdriver Tool ID</strong> zone 1–3 Inside / Outside</td><td>0, 1</td><td>0</td></tr><tr><td><strong>Battens Tool ID</strong> zone Inside / Outside</td><td>the nailers of the machine</td><td>25</td></tr><tr><td><strong>Milling tool id</strong></td><td>28, 48</td><td>28</td></tr><tr><td><strong>Sawing tool id</strong></td><td>23, 33, 43</td><td>23</td></tr><tr><td><strong>Drilling tool id</strong></td><td>22, 42</td><td>22</td></tr><tr><td><strong>Gluing tool id</strong></td><td>29, 49, 29+49</td><td>29</td></tr></tbody></table><p>At the moment the screwer follows the nailer of the zone, drilling always uses tool 22, and glue lines always use tool 29, or 29 and 49 for twin gluing. Twin gluing falls back to one head on panels lower than the <strong>Min height to use twin gluing</strong> of the machine setup.</p><h3 id="default-job-options" tabindex="-1">Default job options <a class="header-anchor" href="#default-job-options" aria-label="Permalink to &quot;Default job options&quot;">​</a></h3><p>Each machine setup has a <strong>MOB v2 panel file</strong> tab with its own default job options. They fill the station&#39;s block when you pick the line in the report form, and they are also used by generation templates. Set them once there, and change them in the report form only for the file you are making.</p><h3 id="frame-station-v2" tabindex="-1">Frame Station V2 <a class="header-anchor" href="#frame-station-v2" aria-label="Permalink to &quot;Frame Station V2&quot;">​</a></h3><p>A Frame Station builds the frame only, so its block is shorter: <strong>Production starting side</strong>, <strong>Shift mode</strong>, <strong>File generation with operations that exceeds the machine sizes</strong>, <strong>Frame layer orientation</strong>, <strong>Use Custom Matrix pattern</strong>, <strong>Minimal framing CtC</strong>, <strong>Frame gluing tool id</strong>, <strong>Frame sawing tool id</strong> and <strong>Max distance between glue lines for joining them</strong>. It usually owns zone 0, so its starting side and shift mode apply to the whole line. See <a href="/guide/machine_files/machines/frame_station/">Frame Station</a>.</p><h3 id="robobrick" tabindex="-1">Robobrick <a class="header-anchor" href="#robobrick" aria-label="Permalink to &quot;Robobrick&quot;">​</a></h3><table><thead><tr><th>Option</th><th>Choices</th><th>Default</th></tr></thead><tbody><tr><td><strong>Max distance between Glue lines for joining them</strong></td><td>mm</td><td>100</td></tr><tr><td><strong>UUID Export mode</strong></td><td>IFC GID (base64) (produuz.it standard), IFC GID converted to canonical UUID v4</td><td>IFC GID (base64)</td></tr></tbody></table><p><strong>UUID Export mode</strong> decides how the id of each brick is written. <strong>Use optimized mode</strong> is also shown and has no effect at the moment. See <a href="/guide/machine_files/machines/robobrick/">Robobrick</a>.</p><h3 id="isolation-machine" tabindex="-1">Isolation machine <a class="header-anchor" href="#isolation-machine" aria-label="Permalink to &quot;Isolation machine&quot;">​</a></h3><p><strong>Production starting side</strong>, <strong>Shift mode</strong>, and <strong>Export Isolation as CSV</strong>, which adds a CSV file of the insulation shots next to the MOB v2 file. See <a href="/guide/machine_files/machines/isolation/">Isolation machine</a>.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p><img src="'+d+'" alt="What the ZIP of a MOB v2 file holds"></p><ol><li><strong>One <code>.mob2</code> file per design</strong>, named after the design and its revision, in a folder per phase and batch. Several panels of the same design share the file.</li><li><strong><code>.orientation.txt</code></strong>: what each station used to place the panel: its zones, its machine zero, its starting side and orientation settings, and which station owns zone 0. Open it when a file comes out mirrored.</li><li><strong><code>_isolation.csv</code></strong>, when an Isolation station has <strong>Export Isolation as CSV</strong> on.</li><li>A <strong>multipanel group</strong> gets one file named after the group, with no revision. See <a href="/guide/management/multipanel_groups/">Multipanel Groups</a>.</li><li><strong><code>pics/</code></strong>: the operation drawings, one per zone and kind: framing nails, operations (nailing, milling and drilling, with the order and the nail counts), plates layout, battens, bricks, insulation and the nail context. Which ones are made is set by the <strong>SVG Drawings</strong> switches of the machine setup that owns zone 0.</li></ol><p>The operation drawings are also added to each panel, behind the <strong>MOB2</strong> button of the <a href="/guide/viewer/">viewer</a>. Each new report replaces them.</p><p>The <code>.mob2</code> files stay with the report: download them from <strong>Production files</strong>.</p><p>If a panel fails, it is left out of the ZIP and the report still finishes. You get a message with the reason (<em>Unknown error generating mob2 file: …</em>) when <strong>Errors on report generation</strong> is on in <a href="/guide/account/">Account → Notifications</a>.</p><h2 id="when-something-is-wrong" tabindex="-1">When something is wrong <a class="header-anchor" href="#when-something-is-wrong" aria-label="Permalink to &quot;When something is wrong&quot;">​</a></h2><table><thead><tr><th>What you see</th><th>Look at</th></tr></thead><tbody><tr><td>The panel is missing from the ZIP</td><td>The message you got. Common causes: the model has no bottom or top rail, the machine setup has no configuration file, or a station of the line has a machine that is not a MOB v2 machine.</td></tr><tr><td>A face or a zone is missing</td><td>The <strong>Zones</strong> of the stations. A zone listed on no station is not produced.</td></tr><tr><td>A zone is produced by the wrong station</td><td>Two stations list it: the first one in the line wins.</td></tr><tr><td>No plate nailing</td><td>The model has no nail line elements, or the configuration file declares no nailers.</td></tr><tr><td>A tool is not in the list</td><td>The configuration file does not declare it. Upload the current file in the <strong>Machine file</strong> tab.</td></tr><tr><td>Twin nailing came out with one head</td><td>The panel is lower than <strong>Minimum panel height for twin nailing</strong>.</td></tr><tr><td>Frame nailing replaced by flooring commands</td><td>The configuration file declares flooring stations.</td></tr><tr><td>The panel is mirrored or starts on the wrong face</td><td>The <code>.orientation.txt</code> file, the starting side of the station that owns zone 0, and the orientation settings of the machine setups. See <a href="/guide/machine_files/machines/mobi_one/#when-a-file-comes-out-mirrored">Mobi One</a>.</td></tr><tr><td>Holes milled that the model does not mill</td><td>Holes are found from the openings of the plates.</td></tr><tr><td>Small round holes missing</td><td>Holes smaller than the <strong>Minimal milling radius to include in mob2</strong> of the machine setup are left out.</td></tr></tbody></table>',91),g=[p];function m(f,u,w,b,y,T){return n(),o("div",null,g)}const x=t(c,[["render",m]]);export{S as __pageData,x as default};
